with base as (select id, full_name, email, job_title, salary, hire_date, is_remote, level, case when is_remote then 'Yes' else 'No' end as is_remote_label, upper(job_title) as job_title_upper, coalesce(job_title, 'N/A') as resolved_job_title from employees where hire_date >= to_date('2023-12-13') and manager_id is not null and full_name like 'K%') select * from (select job_title, level, salary from base) src pivot (max(salary) as value_sum for level in ('L5', 'L3', 'L1'));
